function AppointmentModal({ customers, employees, appointments, onClose, onSave, initial, weatherDaily }) {
  const [title, setTitle] = useState(initial?.title || "");
  const [customerId, setCustomerId] = useState(initial?.customerId || customers[0]?.id || "");
  const [employeeId, setEmployeeId] = useState(initial?.employeeId || employees[0]?.id || "");
  const [date, setDate] = useState(initial?.date || todayISO());
  const [start, setStart] = useState(initial?.start || "09:00");
  const [end, setEnd] = useState(initial?.end || "10:00");
  const [error, setError] = useState("");
  const forecast = (weatherDaily || []).find(d => d.date === date);
  return (
    <Modal title={initial ? "Επεξεργασία ραντεβού" : "Νέο ραντεβού"} onClose={onClose}>
      <label style={labelStyle}>Τίτλος</label>
      <input style={inputStyle} value={title} onChange={e => setTitle(e.target.value)} placeholder="π.χ. Επισκευή γραμμής" />
      <label style={labelStyle}>Πελάτης</label>
      <select style={inputStyle} value={customerId} onChange={e => setCustomerId(e.target.value)}>
        {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
      </select>
      <label style={labelStyle}>Υπάλληλος</label>
      <select style={inputStyle} value={employeeId} onChange={e => setEmployeeId(e.target.value)}>
        {employees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
      </select>
      <label style={labelStyle}>Ημερομηνία</label>
      <input style={inputStyle} type="date" value={date} onChange={e => setDate(e.target.value)} />
      {forecast && (
        <div style={{
            display: "flex", alignItems: "center", gap: 8, marginBottom: 12, padding: "8px 12px",
            borderRadius: 8, fontSize: 13,
            background: (forecast.precip >= 50 || forecast.tempMax >= 35) ? "rgba(255,107,107,0.12)" : NAVY_3,
            border: `1px solid ${(forecast.precip >= 50 || forecast.tempMax >= 35) ? DANGER : CARD_BORDER}`,
            color: DARK
          }}>
          <span style={{ fontSize: 18 }}>{weatherIcon(forecast.code)}</span>
          <span>
            {weatherLabel(forecast.code)}, {forecast.tempMax}°C
            {forecast.precip >= 50 && <b style={{ color: DANGER }}> · Πιθανότητα βροχής {forecast.precip}%</b>}
            {forecast.tempMax >= 35 && <b style={{ color: DANGER }}> · Υπερβολική ζέστη</b>}
          </span>
        </div>
      )}
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ flex: 1 }}>
          <label style={labelStyle}>Ώρα έναρξης</label>
          <input style={inputStyle} type="time" value={start} onChange={e => setStart(e.target.value)} />
        </div>
        <div style={{ flex: 1 }}>
          <label style={labelStyle}>Ώρα λήξης</label>
          <input style={inputStyle} type="time" value={end} onChange={e => setEnd(e.target.value)} />
        </div>
      </div>
      {error && <div style={{ color: DANGER, fontSize: 12, marginBottom: 10 }}>{error}</div>}
      <button className="ltc-btn" style={{ ...btnPrimary, width: "100%" }} onClick={() => {
        if (!title) { setError("Συμπληρώστε τίτλο."); return; }
        if (end <= start) { setError("Η ώρα λήξης πρέπει να είναι μετά την έναρξη."); return; }
        const conflict = appointments.some(a => a.employeeId === employeeId && a.date === date && start < a.end && end > a.start);
        if (conflict) { setError("Ο υπάλληλος έχει ήδη ραντεβού αυτή την ώρα."); return; }
        onSave({ title, customerId, employeeId, date, start, end });
      }}>{initial ? "Αποθήκευση αλλαγών" : "Καταχώρηση"}</button>
    </Modal>
  );
}

function PaymentModal({ customer, onClose, onSave }) {
  const [mode, setMode] = useState("full");
  const [branchId, setBranchId] = useState("");
  const [amount, setAmount] = useState(customer ? String(customer.balance) : "0");
  const [error, setError] = useState("");
  if (!customer) return null;
  const branches = customer.branches || [];
  const maxAmount = branchId ? (branches.find(b => b.id === branchId)?.balance || 0) : customer.balance;
  return (
    <Modal title={`Είσπραξη — ${customer.name}`} onClose={onClose}>
      <div style={{ fontSize: 13, color: TEXT_MUTED, marginBottom: 14 }}>
        Τρέχον υπόλοιπο: <b style={{ color: DARK }}>{fmtEUR(customer.balance)}</b>
      </div>
      {branches.length > 0 && (
        <>
          <label style={labelStyle}>Παρακλάδι</label>
          <select style={inputStyle} value={branchId} onChange={e => {
            const newBranchId = e.target.value;
            setBranchId(newBranchId);
            const newMax = newBranchId ? (branches.find(b => b.id === newBranchId)?.balance || 0) : customer.balance;
            if (mode === "full") setAmount(String(newMax));
            setError("");
          }}>
            <option value="">Γενικά (συνολικό υπόλοιπο πελάτη)</option>
            {branches.map(b => <option key={b.id} value={b.id}>{b.name} — {fmtEUR(b.balance || 0)}</option>)}
          </select>
        </>
      )}
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <button
          onClick={() => { setMode("full"); setAmount(String(maxAmount)); setError(""); }}
          style={{ flex: 1, padding: "8px 10px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600,
            border: `1px solid ${mode === "full" ? BLUE : CARD_BORDER}`,
            background: mode === "full" ? BLUE : NAVY_3, color: mode === "full" ? "white" : DARK }}>
          Πλήρης εξόφληση
        </button>
        <button
          onClick={() => { setMode("partial"); setError(""); }}
          style={{ flex: 1, padding: "8px 10px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600,
            border: `1px solid ${mode === "partial" ? BLUE : CARD_BORDER}`,
            background: mode === "partial" ? BLUE : NAVY_3, color: mode === "partial" ? "white" : DARK }}>
          Μέρος του ποσού
        </button>
      </div>
      {mode === "partial" && (
        <>
          <label style={labelStyle}>Ποσό είσπραξης (€)</label>
          <input style={inputStyle} type="number" value={amount} onChange={e => setAmount(e.target.value)}
            placeholder={`έως ${fmtEUR(maxAmount)}`} />
        </>
      )}
      {error && <div style={{ color: DANGER, fontSize: 12, marginBottom: 10 }}>{error}</div>}
      <button className="ltc-btn" style={{ ...btnPrimary, width: "100%" }} onClick={() => {
        const val = Number(amount);
        if (!val || val <= 0) { setError("Εισάγετε έγκυρο ποσό."); return; }
        if (val > maxAmount) { setError(branchId ? "Το ποσό δεν μπορεί να ξεπερνά το υπόλοιπο του παρακλαδιού." : "Το ποσό δεν μπορεί να ξεπερνά το υπόλοιπο."); return; }
        onSave(val, mode === "full" || val === maxAmount, branchId || null);
      }}>Καταχώρηση είσπραξης</button>
    </Modal>
  );
}

function TaskModal({ employees, onClose, onSave, initial }) {
  const [title, setTitle] = useState(initial?.title || "");
  const [assigneeId, setAssigneeId] = useState(initial?.assigneeId || employees[0]?.id || "");
  const [priority, setPriority] = useState(initial?.priority || "Μεσαία");
  const [deadline, setDeadline] = useState(initial?.deadline || todayISO());
  const [error, setError] = useState("");
  return (
    <Modal title={initial ? "Επεξεργασία εργασίας" : "Νέα εργασία"} onClose={onClose}>
      <label style={labelStyle}>Τίτλος εργασίας</label>
      <input style={inputStyle} value={title} onChange={e => setTitle(e.target.value)} placeholder="π.χ. Παραγγελία υλικών" />
      <label style={labelStyle}>Ανάθεση σε</label>
      <select style={inputStyle} value={assigneeId} onChange={e => setAssigneeId(e.target.value)}>
        {employees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
      </select>
      <label style={labelStyle}>Προτεραιότητα</label>
      <select style={inputStyle} value={priority} onChange={e => setPriority(e.target.value)}>
        <option>Υψηλή</option><option>Μεσαία</option><option>Χαμηλή</option>
      </select>
      <label style={labelStyle}>Προθεσμία</label>
      <input style={inputStyle} type="date" value={deadline} onChange={e => setDeadline(e.target.value)} />
      {error && <div style={{ color: DANGER, fontSize: 12, marginBottom: 10 }}>{error}</div>}
      <button className="ltc-btn" style={{ ...btnPrimary, width: "100%" }} onClick={() => {
        if (!title) { setError("Συμπληρώστε τίτλο εργασίας."); return; }
        onSave({ title, assigneeId, priority, deadline });
      }}>{initial ? "Αποθήκευση αλλαγών" : "Δημιουργία"}</button>
    </Modal>
  );
}
